IF EXISTS (SELECT 1 FROM inserted i JOIN deleted d ON d.Id=i.Id
    WHERE i.ProjectId<>d.ProjectId OR i.DefectId<>d.DefectId OR i.MutationRevision<=d.MutationRevision)
